		private BindingSet merge(BindingSet outer, BindingSet fragment) {
			QueryBindingSet merged = new QueryBindingSet(outer);
			for (String name : fragment.getBindingNames()) {
				if (!merged.hasBinding(name)) {
					Value value = fragment.getValue(name);
					if (value != null) {
						merged.addBinding(name, value);
					}
				}
			}
			return merged;
		}

